import React, { useEffect, useState } from "react";
import api from "../api";
import { io } from "socket.io-client";
// The type describing ONE ticket
type Ticket = {
  _id: string;
  title: string;
  description?: string;
  status: "open" | "in_progress" | "closed";
  category: "billing" | "technical" | "general";
  priority: "low" | "medium" | "high";
  createdBy: any;
  assignee: any;
};

const socket = io("http://localhost:5050", { withCredentials: true });

const InternalDashboard: React.FC = () => {
  const [tickets, setTickets] = useState<Ticket[]>([]);

  // Load tickets assigned to this internal user
  const fetchTickets = async () => {
    try {
      const res = await api.get<Ticket[]>("/tickets");
      setTickets(res.data);
    } catch (err) {
      console.error("Error fetching tickets:", err);
    }
  };

  useEffect(() => {
    fetchTickets();

    socket.on("ticketUpdated", () => {
      fetchTickets();
    });

    socket.on("ticketCreated", () => {
      fetchTickets();
    });

    return () => {
      socket.off("ticketUpdated");
      socket.off("ticketCreated");
    };
  }, []);

  return (
    <div>
      <h1>Internal Dashboard</h1>

      <h2>Assigned Tickets</h2>
      <ul>
        {tickets.map((t) => (
          <li key={t._id}>
            <strong>{t.title}</strong> — {t.status}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default InternalDashboard;
